from AlgorithmImports import *
from collections import deque
from decimal import Decimal


class IndependentDailyStrategies(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy_closes = deque(maxlen=101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.rsi_period = 14
        self.rsi_changes = []
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if symbol not in data.Bars:
                return
            bars[ticker] = data.Bars[symbol]

        spy_close = bars["SPY"].Close
        aapl_close = bars["AAPL"].Close

        self.spy_closes.append(spy_close)

        if self.aapl_previous_close is not None:
            if aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            change = aapl_close - self.aapl_previous_close
            gain = max(change, 0)
            loss = max(-change, 0)

            if self.rsi_average_gain is None:
                self.rsi_changes.append((gain, loss))
                if len(self.rsi_changes) == self.rsi_period:
                    self.rsi_average_gain = sum(x[0] for x in self.rsi_changes) / self.rsi_period
                    self.rsi_average_loss = sum(x[1] for x in self.rsi_changes) / self.rsi_period
            else:
                self.rsi_average_gain = (
                    self.rsi_average_gain * (self.rsi_period - 1) + gain
                ) / self.rsi_period
                self.rsi_average_loss = (
                    self.rsi_average_loss * (self.rsi_period - 1) + loss
                ) / self.rsi_period

            if self.rsi_average_gain is not None:
                if self.rsi_average_loss == 0:
                    self.aapl_rsi = Decimal(100)
                else:
                    rs = self.rsi_average_gain / self.rsi_average_loss
                    self.aapl_rsi = Decimal(100) - Decimal(100) / (Decimal(1) + rs)

        self.aapl_previous_close = aapl_close

        if len(self.spy_closes) < 101 or self.aapl_rsi is None:
            return

        spy_values = list(self.spy_closes)
        previous_spy_sma = sum(spy_values[:100]) / 100
        current_spy_sma = sum(spy_values[1:]) / 100
        previous_spy_close = spy_values[-2]

        spy_crosses_above = (
            previous_spy_close <= previous_spy_sma and
            spy_close > current_spy_sma
        )
        spy_crosses_below = (
            previous_spy_close >= previous_spy_sma and
            spy_close < current_spy_sma
        )

        # Evaluate all sells before any buys.
        if self.strategy_a_shares > 0 and spy_crosses_below:
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crosses_above:
            shares = int((self.Portfolio.TotalPortfolioValue * Decimal("0.40")) / spy_close)
            if shares > 0:
                self.MarketOrder(self.symbols["SPY"], shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            purchase_amount = Decimal(20000)
            if self.Portfolio.Cash >= purchase_amount:
                shares = int(purchase_amount / aapl_close)
                if shares > 0:
                    self.MarketOrder(self.symbols["AAPL"], shares)
                    self.strategy_b_shares = shares
