        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.spy_sma_history = RollingWindow[float](2)
        self.spy_close_history = RollingWindow[float](2)
        self.aapl_close_history = RollingWindow[float](4)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        self.spy_close_history.Add(float(spy_bar.Close))
        self.aapl_close_history.Add(float(aapl_bar.Close))

        if self.spy_sma.IsReady:
            self.spy_sma_history.Add(float(self.spy_sma.Current.Value))

        if (
            not self.spy_sma.IsReady
            or not self.aapl_rsi.IsReady
            or self.spy_sma_history.Count < 2
            or self.spy_close_history.Count < 2
            or self.aapl_close_history.Count < 4
        ):
            return

        spy_close_today = self.spy_close_history[0]
        spy_close_yesterday = self.spy_close_history[1]
        spy_sma_today = self.spy_sma_history[0]
        spy_sma_yesterday = self.spy_sma_history[1]

        # Evaluate sells before buys.
        if self.strategy_a_shares > 0:
            if (
                spy_close_yesterday >= spy_sma_yesterday
                and spy_close_today < spy_sma_today
            ):
                self.MarketOrder(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0:
            if (
                spy_close_yesterday <= spy_sma_yesterday
                and spy_close_today > spy_sma_today
            ):
                quantity = int(
                    (0.40 * self.Portfolio.TotalPortfolioValue) / spy_bar.Close
                )
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0:
            red_three_days = (
                self.aapl_close_history[0] < self.aapl_close_history[1]
                and self.aapl_close_history[1] < self.aapl_close_history[2]
                and self.aapl_close_history[2] < self.aapl_close_history[3]
            )

            if red_three_days and self.Portfolio.Cash >= 20_000:
                quantity = int(20_000 / aapl_bar.Close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_shares = quantity
